const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define a region of interest roughly covering Antarctica and the surrounding Southern Ocean
  // where the ozone hole typically forms. 3000 km buffer around the South Pole.
  const antarctica = ee.Geometry.Point([0, -90]).buffer(3000000); // 3000 km radius

  // Date ranges for comparison
  const date_aug_start = '2024-08-26';
  const date_aug_end = '2024-08-30';
  const date_sep_start = '2024-09-26';
  const date_sep_end = '2024-09-30';

  const OZONE_THRESHOLD_DU = 220; // Dobson Units for ozone hole definition
  const SCALE = 25000; // Resolution for reduceRegion, in meters. OMI native resolution is ~27km.

  // 2. Data Acquisition & Check
  const getOzoneCollection = (startDate, endDate) => {
    let collection = ee.ImageCollection('NASA/Aura/OMI/OMPRODOZ_V003')
      .filterDate(startDate, endDate)
      .filterBounds(antarctica);

    // Apply quality mask (QA_TCO3 = 0 for good quality)
    collection = collection.map(image => image.updateMask(image.select('QA_TCO3').eq(0)));

    return collection;
  };

  const calculateOzoneHoleArea = (collection, periodName) => {
    const size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for ${periodName}.`);
      return { area: null, count: 0, size: 0 }; // Indicate calculation failure
    }
    console.log(`${periodName} Images: ${size}`);

    // Create a mosaic of the collection for the period
    const composite = collection.mean().select('DU_TCO3');

    // Check if composite has valid data after masking and reduction
    const checkComposite = composite.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: antarctica,
      scale: SCALE,
      maxPixels: 1e9
    });
    const validPixelsInComposite = checkComposite.get('DU_TCO3').getInfo();

    if (validPixelsInComposite === 0 || validPixelsInComposite === null) {
      console.log(`No valid pixels in composite for ${periodName} after quality masking.`);
      return { area: null, count: 0, size: size }; // Indicate calculation failure
    }

    // Identify ozone hole pixels (< 220 DU)
    const ozoneHoleMask = composite.lt(OZONE_THRESHOLD_DU);

    // Calculate area of each pixel in square meters
    const pixelArea = ee.Image.pixelArea();

    // Multiply the ozone hole mask by pixel area to get area of ozone hole per pixel
    const ozoneHoleAreaImage = ozoneHoleMask.multiply(pixelArea);

    // Sum up the areas for the entire region
    const stats = ozoneHoleAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: antarctica,
      scale: SCALE,
      maxPixels: 1e9 // Allow processing of a large number of pixels
    });

    const totalAreaSqM = stats.get('DU_TCO3').getInfo(); // The band 'DU_TCO3' was selected earlier

    // Validate result
    if (totalAreaSqM === null) {
      console.log(`Calculation of ozone hole area failed for ${periodName}. Result is null.`);
      return { area: null, count: validPixelsInComposite, size: size };
    }

    // Convert to million square kilometers (1e6 m^2 = 1 km^2, so 1e12 m^2 = 1 M km^2)
    const totalAreaM_sq_km = totalAreaSqM / 1e12; // M km^2

    // Check pixel count after ozone hole masking
    const ozoneHolePixelCount = ozoneHoleAreaImage.gt(0).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: antarctica,
      scale: SCALE,
      maxPixels: 1e9
    }).get('DU_TCO3').getInfo();

    if (ozoneHolePixelCount === 0) {
      console.log(`No ozone hole pixels found for ${periodName}.`);
    }

    return { area: totalAreaM_sq_km, count: ozoneHolePixelCount, size: size };
  };

  // Get data and calculate for August
  const collection_aug = getOzoneCollection(date_aug_start, date_aug_end);
  const result_aug = calculateOzoneHoleArea(collection_aug, "August 2024");

  // Get data and calculate for September
  const collection_sep = getOzoneCollection(date_sep_start, date_sep_end);
  const result_sep = calculateOzoneHoleArea(collection_sep, "September 2024");

  // Check for C1 (Empty Collection)
  if (result_aug.size === 0 || result_sep.size === 0) {
    console.log("C1: Empty Collection (No images found for one or both comparison points).");
    return;
  }

  // Check for C2 (No Valid Pixels after quality masking or no ozone hole pixels)
  // This specifically checks if *any* ozone hole pixels were found.
  // If result.area is 0.0, it's a valid zero (no ozone hole), not C2.
  if (result_aug.area === null || result_sep.area === null) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid during area calculation).");
    return;
  }

  // 5. Validation & Final Answer
  const area_aug = result_aug.area;
  const area_sep = result_sep.area;

  console.log(`August 26-30, 2024 Ozone Hole Area: ${area_aug.toFixed(2)} M km^2 (Pixels: ${result_aug.count})`);
  console.log(`September 26-30, 2024 Ozone Hole Area: ${area_sep.toFixed(2)} M km^2 (Pixels: ${result_sep.count})`);

  if (area_sep > area_aug) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
